import{_ as n,C as a,o as r,c as l,j as e,a as s,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"断占总诀篇之二：万物赋","description":"通过万物、饮食与歌诀，扩展八卦取象与克应的观察范围。","frontmatter":{"title":"断占总诀篇之二：万物赋","description":"通过万物、饮食与歌诀，扩展八卦取象与克应的观察范围。","category":"学习计划 · 第三阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/duan-zhan-zong-jue/myriad-things-ode.md","filePath":"yijing/meihua-yishu/duan-zhan-zong-jue/myriad-things-ode.md","lastUpdated":1787738987000}'),p={name:"yijing/meihua-yishu/duan-zhan-zong-jue/myriad-things-ode.md"};function h(c,t,b,g,u,m){const d=a("DaoTextReading");return r(),l("div",null,[t[0]||(t[0]=e("h1",{id:"【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌",tabindex:"-1"},[s("【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌 "),e("a",{class:"header-anchor",href:"#【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌","aria-label":'Permalink to "【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌"'},"​")],-1)),t[1]||(t[1]=e("blockquote",null,[e("p",null,"本篇是全书最大的「象意词典」与「断法总歌」，万物赋讲克应取象，饮食篇讲八卦饮食断法，观物玄妙歌诀讲八卦物性，诸事响应歌是全书断法的歌诀总结。")],-1)),t[2]||(t[2]=e("hr",null,null,-1)),t[3]||(t[3]=e("h2",{id:"📜-原文",tabindex:"-1"},[s("📜 原文 "),e("a",{class:"header-anchor",href:"#📜-原文","aria-label":'Permalink to "📜 原文"'},"​")],-1)),i(d,{colophon:"万物赋 · 饮食篇 · 玄妙歌诀",tone:"ink",sections:[{id:"sec-01",label:"万物赋",showLabel:!0,sentences:[["人",{text:"禀",glossary:"g01"},"阴阳，卦分先后。"],["达时务者，近取诸身，远取诸物。"],["观物理者，静则乎地，动则乎天。"],["原夫万物有数，易数无穷。"]]},{id:"sec-01-1",label:"",showLabel:!0,sentences:[["动静可知，不出于玄天之外。"],["吉凶必见，莫逃乎爻象之中。"],["未成卦以前，必虚心而求应；既成卦以后，复观",{text:"刻应",glossary:"g03"},"以为断。"],["声音言语，傍人",{text:"谶兆",glossary:"g02"},"，当遇形影往来，我心指实皆是，及其六爻以定，三天既生，始寻卦象之端，终测",{text:"刻应",glossary:"g03"},"之理。"]]},{id:"sec-01-2",label:"",showLabel:!0,sentences:[["是以逢吉兆而终知有喜，见凶识而不免乎凶。"],["故欲知他人家之事，必须凭我耳目之闻见。"]]},{id:"sec-01-3",label:"",showLabel:!0,sentences:[["未成卦而闻见之，乃已生之事。"],["既定卦而观察之，乃未来之机。"],["或闻何处喧闹，主有斗争；或听此间笑语，必逢吉庆；见妇啼叹，其家阴小有灾；东至军来，必有官司词讼；或逢枷锁而枷锁临身；倘遇鞭杖而鞭杖必至。"]]},{id:"sec-01-4",label:"",showLabel:!0,sentences:[["若屠而负肉，此为骨肉有灾；倘逢血光，而又恐灾于",{text:"孳畜",glossary:"g04"},"。"],[{text:"师巫乐饵",glossary:"g05"},"，病患临门。"],["见",{text:"诐",glossary:"g06"},"则有犯家先，逢酒则欠神愿。"],["阴人至则女子有厄，阳人至则男子当灾。"],["又须八卦中分，不可一例而论。"]]},{id:"sec-01-5",label:"",showLabel:!0,sentences:[["卦吉而爻象又吉，祸患终无；卦凶而识兆又凶，灾殃难免。"],[{text:"披麻带孝",glossary:"g07"},"，必然孝服临头；持杖而号，定主号泣满室。"],["其人忧终是为忧，其人喜还须有喜。"],["故当观色察形，以为决意断心。"]]},{id:"sec-01-6",label:"",showLabel:!0,sentences:[["其或鼓乐声喧，又见酒杯器皿，若不迎婚嫁娶，定须会客宴酣。"],["欲知应在何日，须观爻象值数。"]]},{id:"sec-01-7",label:"",showLabel:!0,sentences:[["巽五日而坤八日，离三朝而坎六朝。"],["又观远近克应，以断得买之相期。"],["应远，则全卦相同；应近，而各时同断。"]]},{id:"sec-01-8",label:"",showLabel:!0,sentences:[["假如天地否卦，上天一而下地八；设若泽火革卦，上兑二而下离三。"],["依此推之，万无一失。"],["此人物之兆，察之可推也。"],["及其鸟兽之应，仍验之有准。"],["鹊噪而喜色已动，鸦鸣而祸事将来。"]]},{id:"sec-01-9",label:"",showLabel:!0,sentences:[["牛羊猪犬，日晨不见，金日遇之，六畜有损。"],["木日见猪养猪，必成。"],["庚日见鸡鸣，丁日见羊过，此乃凶刃之杀。"],["己日值马来，壬日猪过，此皆食禄之兆。"],["见吉兆而百事亨通，逢凶谶而诸事阻滞。"],["或若求财问利，须凭克应。"],["以言柜箱为藏财之用，绳索为穿钱之物。"],["逢金帛宝货之类，理必有成。"],["遇刀刃剑具之器，损而无益。"]]},{id:"sec-01-10",label:"",showLabel:!0,sentences:[["又看原卦，不可执一。"],["逢财而有财，无财而无益。"],["凡物成器，方系得全，缺损破碎，有之不足。"],["或问婚姻，理亦相似。"],["物团圆，指日而成；物破损，中逢阻折。"],["此又是一家，闻奥理明，万事昭然。"],["逢柴炭主忧，折麦主悲。"],["米必奇，豆必伤。"],["末与鞋，万事和谐；棋与药，与人期约。"],["斧锯必有修造，粮储必有远行。"],["闻禽鸣，谋事虚说。"],["听鼓声，交易空虚。"],["拭目润睫，内有哭泣之事；持刃见血，外有虫毒之讲。"],["克应既明，饮食同断。"],["见水为饮食酒汤，遇火为煎炮烤炙。"],["见米为一饭之得，提壶为酌杯之礼。"],["水乃鱼暇水中物味，土乃牛羊土内菜蔬。"],["姜面为辛味辣羹，",{text:"刀砧",glossary:"g08"},"乃董腥美味。"],["此三天之克应，万物之",{text:"枢机",glossary:"g12"},"。"],["能达此者尚其秘之。"]]},{id:"sec-02",label:"饮食篇",showLabel:!0,sentences:[["夫干之为象也，圆坚而味辛，取象乎卯，为牲之首，为马为猪，秋得之而食禄盛，夏得之而食禄衰。"],["春为时新之物，水果蔬菜之属；冬为冷物，隔宿之食。"],["有坎乃江湖海味，有水而蔬果珍羞。"],["艮为土物同烹，离乃火边煎炙。"],["秋为蟹，春为马。"]]},{id:"sec-02-1",label:"",showLabel:!0,sentences:[["凡内必多肉，其味必辛，盛有瓦器，伴有金樽。"],["其于菜也为芹，其于物也带羽。"],["克生生回，食必鹅鸭。"],["生出克入，野菜无名。"]]},{id:"sec-02-2",label:"",showLabel:!0,sentences:[["坤其于坤也，远客至，故人来，所用必瓦器，所食米果之味。"],["静则梨枣茄芋，动则鱼虾鲜羊。"],["无骨肉脯，杀亦为藏，藏亦为肚肠。"],["遇客必妇人，克此必主口舌。"],["克出生回，乃牲之味；克入生物，乃集物之烹。"]]},{id:"sec-02-3",label:"",showLabel:!0,sentences:[["见干、兑，细切薄披；见震、巽而新生旧煮，其色黑黄，其味甘甜，水火并之，蒸炊而已。"],["四时皆为米麦之味，必带麻姜。"],["仔细推详必有验也。"]]},{id:"sec-02-4",label:"",showLabel:!0,sentences:[["巽之为卦，主文书",{text:"柬约",glossary:"g19"},"之间，讲论之际，外客婚姻，故人旧交。"],["或主远信近期，其色白青，其性曲直，其味酸，其象长。"],["桃李木瓜，斋辣素食，为鱼为鸡，其豆其面，非济执而得之，必锄掘而得之。"]]},{id:"sec-02-5",label:"",showLabel:!0,sentences:[["有干、兑，食之而致病，有坤，得之非难。"],["炊为炒菜蔬，离为炒茶，带坎于中，酒汤其食。"],["其无生，半斋半荤。"],["其在艮也，会邻里，有贵人。"],["食物不多，适口而已。"],["其桔油菜果蔬，斫伐于山林带节，虎狗兔鹿，渔捕网罗，米麻面麦。"],["克入集食，克出羊肉。"],["克入口舌，是非阴灾，极不可食。"],["其味甘甜，其色玄黄。"]]},{id:"sec-02-6",label:"",showLabel:!0,sentences:[["坎为水象也，水近信至海内，味香有细鳞，或四足。"],["凡曰水族，必可饮食也。"],["或闻箫鼓之声，或在礼乐之所，其色黑，其味咸。"],["克出饮酒，回食鱼。"],["为豕为目，为耳为血。"],["羹汤物味，酒食水酱。"]]},{id:"sec-02-7",label:"",showLabel:!0,sentences:[["遇离而说文书，逢干而为海味。"],["震之为卦，木属也。"],["酒友",{text:"疏狂",glossary:"g20"},"，虚轻怪异。"],["大树之果，园林之蔬，其色青而味酸，其数多，会客少。"],["或有膻臭之气，或有异香之肴。"],["同离多，主盐茶；见坎或为盐醋。"]]},{id:"sec-02-8",label:"",showLabel:!0,sentences:[["离则文书交易，亲戚师儒，坐中多礼貌之人，筵上总英才之士。"],["其物乃煎烤炙烧，其间或茶盐。"],["白日之夕，虽之以烛，春夏之际。"],["凡物带花，老人莫食。"],["心事不宁，少者宜之。"],["宜讲论，即有益。"],["为鸡为雉，为蟹为蛇，色赤味苦，性热而气香。"]]},{id:"sec-02-9",label:"",showLabel:!0,sentences:[["逢坎而酒请之争，逢巽则炒菜而已。"],["兑之为卦，其属白金，其味辛而色白。"],["或远客暴至，或近交争来。"],["凡动物",{text:"刀砧",glossary:"g08"},"，凡味必有辛辣，凡包里腌藏。"],["其于暴也，为菲为菱；其于菜也，为葱为韭。"],["盛而有腥臭，旺而有羊鹅。"],["坐间有潜越之人，或有歌娼之女。"],["单则必然口舌，重则必然欢喜。"],["生出多食，克出好事。"],["夫算其饮食，必须察其动静。"]]},{id:"sec-02-10",label:"",showLabel:!0,sentences:[["故动则有，静则无。"],["以体卦下卦为己卦，上为人卦。"],["下为变为客，互之上为酒，下为食物。"],["取象体之下为食何物，变为客体，下食之不终，生体下吉。"],["互克体之不得食。"],["他人克应亦难食。"],["他人生，他人请，己生体生下，己请人。"],["互受生后不计",{text:"杯杓",glossary:"g18"},"。"],["上体受生客不计数。"],["变生互，客有后至者；互生克，有先去者。"],["取其日时，以互卦用矣。"]]},{id:"sec-03",label:"观物玄妙歌诀",showLabel:!0,sentences:[["观物戏验者，虽云无益于世，学者以此验数，而知圣人作《易》之灵耳。"],["物之于世，必有数焉。"]]},{id:"sec-03-1",label:"",showLabel:!0,sentences:[["故天圆地方，物之形也；天玄地黄，物之色也；天动地静，物之性也；天上地下，物之位也；干刚坤柔，物之体也。"]]},{id:"sec-03-2",label:"",showLabel:!0,sentences:[["故干之为卦，刚而圆，贵而坚，为金为玉，为赤为圆，为大为首，为上之果物。"]]},{id:"sec-03-3",label:"",showLabel:!0,sentences:[["见兑为毁拆，逢坎而沉溺，见离为炼煅之金，震为有动之物，巽为木果为圆，坤、艮土中之石，得火而成器。"]]},{id:"sec-03-4",label:"",showLabel:!0,sentences:[["兑为剑锋之锐，秋得而价高，夏得之而衰矣。"],["坤之为卦，其形直而方，其色黑而黄。"]]},{id:"sec-03-5",label:"",showLabel:!0,sentences:[["为文为布，为舆为金。"],["其物象牛，其性恶动。"],["得干乃可圆可方，可贵可贱。"]]},{id:"sec-03-6",label:"",showLabel:!0,sentences:[["震、巽为长器，离为文章，兑为土中出之金，艮为带刚之土石也。"],["震之为卦，其色玄黄而多青，为木为声，为竹为",{text:"萑苇",glossary:"g09"},"，为",{text:"蕃鲜",glossary:"g10"},"及生形。"],["上柔下刚，是性震动而可惊。"]]},{id:"sec-03-7",label:"",showLabel:!0,sentences:[["得干乃为声价之物，得兑为无用之木，见艮山林间之石，见坎有气之类，巽为有枝叶，见离为带花。"],["巽之为卦，其色白，其气香。"],["为草木，为刚为柔。"],["见离为文书，见兑、干为不用，乃遇金刀之物。"],["坤、艮为草木之类，坎、兑为可食之物。"],["为长为直，并震而春生夏长，草木之果蔬。"]]},{id:"sec-03-8",label:"",showLabel:!0,sentences:[["坎之为卦，其色黑，亦可圆可方物。"],["为柔为腐，内则刚物。"],["得之",{text:"卑湿",glossary:"g11"},"之所，多为水中之物。"],["见干亦圆，见兑亦毁。"]]},{id:"sec-03-9",label:"",showLabel:!0,sentences:[["又乃污湿，得震、巽而可食；离、水火既济，假水而出，假火而成。"],["又为滞于物，兑为带口也。"],["震、巽为带枝叶，为带花也。"],["离之为卦也，其色黄而青，体燥，其性则上刚下柔。"],["为山石之物，土瓦之类，小石于大山，为门途之处。"],["为物见干而刚，兑而毁折，坤而土块，巽为草之物，而震为木物类也。"],["坎并为河岸之物，离并为瓦器，震、巽并见篱壁之物。"]]},{id:"sec-03-10",label:"",showLabel:!0,sentences:[["兑之为卦，其色白，其性少柔多刚。"],["为毁折而下，全带口而圆。"],["见干先圆后缺，见艮则金石废器，见震、巽为剥削之物，见坎为水之类。"],["得干而多刚，得坤而多柔，长于西泽之内。"],["于水中之类，得柔而成器也。"]]},{id:"sec-04",label:"诸事响应歌",showLabel:!0,sentences:[["混沌开辟立人极，吉凶回应尤难避。"]]},{id:"sec-04-1",label:"",showLabel:!0,sentences:[["先贤遗下预知音，《皇极》《观梅》出《周易》。"]]},{id:"sec-04-2",label:"",showLabel:!0,sentences:[["玄微浩瀚总无涯，各述繁言人莫记。"]]},{id:"sec-04-3",label:"",showLabel:!0,sentences:[["大抵体宜用卦生，旺相谋为终有益。"]]},{id:"sec-04-4",label:"",showLabel:!0,sentences:[["比和为吉克为凶，生用亦为凶兆矣。"]]},{id:"sec-04-5",label:"",showLabel:!0,sentences:[["问雨天晴无坎兑，",{text:"亢旱",glossary:"g13"},"言之终则是。"]]},{id:"sec-04-6",label:"",showLabel:!0,sentences:[["天时连雨问晴明，艮离",{text:"贲卦",glossary:"g14"},"回应耳。"]]},{id:"sec-04-7",label:"",showLabel:!0,sentences:[["干明坤晦巽多风，震主雷霆定莫疑。"]]},{id:"sec-04-8",label:"",showLabel:!0,sentences:[["凡占人事体克用，诸事亨通须有幸。"]]},{id:"sec-04-9",label:"",showLabel:!0,sentences:[["比和为妙克为凶，又看其中体卦证。"]]},{id:"sec-04-10",label:"",showLabel:!0,sentences:[["干主公门是老人，坤遇阴人曰土应。"]]},{id:"sec-04-11",label:"",showLabel:!0,sentences:[["震为东方或山林，巽亦山林蔬果品。"]]},{id:"sec-04-12",label:"",showLabel:!0,sentences:[["坎为北方并水姓，酒货鱼盐才取定。"]]},{id:"sec-04-13",label:"",showLabel:!0,sentences:[["离言文书炉冶利，亦日南方颜色亦。"]]},{id:"sec-04-14",label:"",showLabel:!0,sentences:[["艮为东北山林材，兑曰西方喜悦是。"]]},{id:"sec-04-15",label:"",showLabel:!0,sentences:[["生体克体亦同方，编记以为诸事应。"]]},{id:"sec-04-16",label:"",showLabel:!0,sentences:[["凡问家宅体为主，旺相须知进田土。"]]},{id:"sec-04-17",label:"",showLabel:!0,sentences:[["生用须云耗散财，比和家世安居处。"]]},{id:"sec-04-18",label:"",showLabel:!0,sentences:[["克体为凶决断之，生产以体为其母。"]]},{id:"sec-04-19",label:"",showLabel:!0,sentences:[["两宜生旺不宜衰，奇偶之中察男女。"]]},{id:"sec-04-20",label:"",showLabel:!0,sentences:[["干卦为阳坤为阴，又有来人爻内取。"]]},{id:"sec-04-21",label:"",showLabel:!0,sentences:[["阴多生女阳生男，此数分明具易理。"]]},{id:"sec-04-22",label:"",showLabel:!0,sentences:[["婚姻生用必难成，比和克用大吉利。"]]},{id:"sec-04-23",label:"",showLabel:!0,sentences:[["若问饮食和生体，必知",{text:"肴馔",glossary:"g15"},"丰厚喜。"]]},{id:"sec-04-24",label:"",showLabel:!0,sentences:[["生用克体饮食难，克用必无比和美。"]]},{id:"sec-04-25",label:"",showLabel:!0,sentences:[["坎兑为酒震为鱼，八卦推求衰旺取。"]]},{id:"sec-04-26",label:"",showLabel:!0,sentences:[["求谋称意是比和，克用谋为迟可已。"]]},{id:"sec-04-27",label:"",showLabel:!0,sentences:[["求名克用名可求，生体比和俱可取。"]]},{id:"sec-04-28",label:"",showLabel:!0,sentences:[["求财克用日有财，生体比和俱称意。"]]},{id:"sec-04-29",label:"",showLabel:!0,sentences:[["交易生体及比和，有利必成无后虑。"]]},{id:"sec-04-30",label:"",showLabel:!0,sentences:[["出行克用用生体，所至其方多得意。"]]},{id:"sec-04-31",label:"",showLabel:!0,sentences:[["坎则乘舟离旱途，干震动则坤艮止。"]]},{id:"sec-04-32",label:"",showLabel:!0,sentences:[["行人克用必来迟，生体比和人即至。"]]},{id:"sec-04-33",label:"",showLabel:!0,sentences:[["成远恒迟升不回，艮阻坎险君须记。"]]},{id:"sec-04-34",label:"",showLabel:!0,sentences:[["若去",{text:"谒人",glossary:"g16"},"体克用，速可追寻依卦断。"]]},{id:"sec-04-35",label:"",showLabel:!0,sentences:[["相生比和终可寻，兑临残缺并井畔。"]]},{id:"sec-04-36",label:"",showLabel:!0,sentences:[["离为",{text:"冶所",glossary:"g17"},"及南方，坤主方器凭推看。"]]},{id:"sec-04-37",label:"",showLabel:!0,sentences:[["疾病最宜体旺相，克用易安药有效。"]]},{id:"sec-04-38",label:"",showLabel:!0,sentences:[["比和凶则有救星，体卦受克为凶兆。"]]},{id:"sec-04-39",label:"",showLabel:!0,sentences:[["离宜服热坎服冷，卦见坤土温补亨。"]]},{id:"sec-04-40",label:"",showLabel:!0,sentences:[["亦把鬼神卦象推，震主娇怪为状貌。"]]},{id:"sec-04-41",label:"",showLabel:!0,sentences:[["巽为自缢井锁枷，坤艮落水及血刃。"]]},{id:"sec-04-42",label:"",showLabel:!0,sentences:[["凡占公讼用宜克，体卦旺相终得理。"]]},{id:"sec-04-43",label:"",showLabel:!0,sentences:[["比和助解最为奇，非止全仗他人力。"]]},{id:"sec-04-44",label:"",showLabel:!0,sentences:[["若问墓穴在何地，坤则平阳巽林里。"]]},{id:"sec-04-45",label:"",showLabel:!0,sentences:[["干宜高葬艮临山，离近人烟兑兴废。"]]},{id:"sec-04-46",label:"",showLabel:!0,sentences:[["比和生体宜葬之，克用尤为大吉利。"]]},{id:"sec-04-47",label:"",showLabel:!0,sentences:[["若人临问听傍言，笑语鸡鸣亦吉美。"]]},{id:"sec-04-48",label:"",showLabel:!0,sentences:[["美物是为祥端推，略举片言通万类。"]]}],glossary:[{id:"g01",term:"禀",pinyin:"bǐng",meaning:"承受，禀受"},{id:"g02",term:"谶兆",pinyin:"chèn zhào",meaning:"预兆，应验的征兆"},{id:"g03",term:"刻应",pinyin:"kè yìng",meaning:"克期应验，在特定时间节点应验"},{id:"g04",term:"孳畜",pinyin:"zī chù",meaning:"牲畜，孳：繁殖"},{id:"g05",term:"师巫乐饵",pinyin:"wū",meaning:"巫师·乐师·药饵，主病患"},{id:"g06",term:"诐",pinyin:"bì",meaning:"邪僻，见诐：见到邪僻之人或物"},{id:"g07",term:"披麻带孝",pinyin:"—",meaning:"穿孝服，主丧事"},{id:"g08",term:"刀砧",pinyin:"zhēn",meaning:"砧板，刀砧：厨刀与砧板，主荤腥美味"},{id:"g09",term:"萑苇",pinyin:"huán wěi",meaning:"芦苇类植物"},{id:"g10",term:"蕃鲜",pinyin:"fān xiān",meaning:"茂盛鲜嫩之物"},{id:"g11",term:"卑湿",pinyin:"bēi shī",meaning:"低洼潮湿之地"},{id:"g12",term:"枢机",pinyin:"shū jī",meaning:"关键·核心，枢：门轴"},{id:"g13",term:"亢旱",pinyin:"kàng hàn",meaning:"极度干旱"},{id:"g14",term:"贲卦",pinyin:"bì guà",meaning:"山火贲，艮上离下，主文饰·晴明"},{id:"g15",term:"肴馔",pinyin:"yáo zhuàn",meaning:"丰盛的菜肴"},{id:"g16",term:"谒人",pinyin:"yè rén",meaning:"拜访·求见他人"},{id:"g17",term:"冶所",pinyin:"yě suǒ",meaning:"冶炼之所，铁匠铺·炉灶处"},{id:"g18",term:"杯杓",pinyin:"bēi sháo",meaning:"杯与勺，泛指饮食器具"},{id:"g19",term:"柬约",pinyin:"jiǎn yuē",meaning:"书信·约定"},{id:"g20",term:"疏狂",pinyin:"shū kuáng",meaning:"放荡不羁"}],"aria-label":"万物赋原文"}),t[4]||(t[4]=o("",99))])}const L=n(p,[["render",h]]);export{y as __pageData,L as default};
